  ?sensor a (brick:Power_Sensor brick:Electric_Power_Sensor).
  ?sensor brick:hasProperty ?equip .
  OPTIONAL { ?equip rdfs:label ?name }
}

SELECT DISTINCT ?k WHERE {
  ?s brick:hasProperty ?o .
  BIND("hasProperty" AS ?k)
} LIMIT 5

SELECT ?sensor ?equip ?eqtype WHERE {
  ?sensor a (brick:Electric_Power_Sensor brick:Power_Sensor) .
  ?sensor brick:isPointOf ?equip .
  ?equip a ?eqtype .
  FILTER (?eqtype != brick:Illuminance_Sensor && ?eqtype != brick:Site)
}

SELECT ?sensor ?ts WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts .
}

